const uiFrameworkIds = new Set(["react", "angular", "vue", "svelte"]);
const metaFrameworkIds = new Set(["nextjs", "nuxt", "sveltekit"]);
const clientStateIds = new Set(["redux-toolkit", "tanstack-query"]);
const ormIds = new Set(["hibernate", "entity-framework-core"]);
const coreCsIds = new Set(["computer-architecture", "compilers", "theory-of-computation", "software-engineering"]);

function profileFor(spec: DepthSpec): DomainProfile {
  if (uiFrameworkIds.has(spec.id)) return uiFrameworkProfile;
  if (metaFrameworkIds.has(spec.id)) return metaFrameworkProfile;
  if (clientStateIds.has(spec.id)) return clientStateProfile;
  if (spec.id === "tailwind-css") return cssFrameworkProfile;
  if (ormIds.has(spec.id)) return ormProfile;
  if (spec.id === "akka") return actorRuntimeProfile;
  if (spec.id === "nodejs") return profiles.runtime;
  if (spec.id === "sql") return profiles.database;
  if (spec.id === "kafka") return streamingPlatformProfile;
  if (spec.id === "airflow" || spec.id === "dbt") return dataPipelineProfile;
  if (coreCsIds.has(spec.id)) return coreCsProfile;
  return profiles[spec.kind];
}

function focusFor(spec: DepthSpec) {
  const raw = focusText[spec.id];
  if (!raw) throw new Error(`Published technology ${spec.id} is missing its specialist A-Z focus map.`);
  const focus = raw.split(";").map((item) => item.trim()).filter(Boolean);
  if (focus.length < 8) throw new Error(`Technology ${spec.id} needs at least eight specialist focus areas.`);
  return focus;
}

function section(
  title: string,
  explanation: string,
  plainEnglish: string,
  analogy: string,
  analogyLimit: string,
  concreteExample: string,
  keyPoints: string[]
) {
  return { title, explanation, plainEnglish, analogy, analogyLimit, concreteExample, keyPoints };
}

function examples(spec: DepthSpec, profile: DomainProfile, focus: string[]) {
  const supplied = spec.code ?? ["Pseudocode", `// ${spec.title}: smallest complete boundary`, `Trace ${profile.unit} through success, failure, and cleanup.`];
  const boundaryCode = `// Architecture pseudocode for ${spec.title}\ninput = validate(rawInput)\nresult = policy.execute(input, dependency)\nreturn present(result)\n// translate known failures once at the outer boundary`;
  const testCode = `// Contract test pseudocode\ngiven(validInput)\nwhen(() => subject.execute(validInput))\nthen(invariantHolds)\nand(noHiddenSideEffectEscapes)\n// repeat with invalid, empty, duplicate, cancelled, and boundary-size input`;
  const diagnosticCode = `# Evidence-first diagnostic loop for ${spec.title}\nrecord version-and-config\nreproduce smallest-failing-case\ncapture logs metrics traces and resource state\ncompare healthy-versus-failing path\nchange one suspected cause\nverify invariant and regression test`;
  const rolloutCode = `# Safe-change pseudocode\nvalidate config and compatibility\nstage to a small cohort\nwatch correctness latency saturation and error signals\nstop on the declared threshold\npromote gradually or roll back\nverify data and external side effects after recovery`;
  return [
    { title: `Smallest complete ${spec.title} slice`, language: supplied[0], code: supplied[1], explanation: `${supplied[2]} Name the input, owned state, output, and cleanup path; then relate the slice to ${focus[0]} and ${focus[1]}.` },
    { title: "Boundary validation without leaking framework concerns", language: "Pseudocode", code: boundaryCode, explanation: `Validation and error translation stay at ${profile.boundary}. Core policy remains testable while ${spec.title}-specific lifecycle and integration behavior remain in adapters.` },
    { title: "Invariant-focused contract test", language: "Pseudocode", code: testCode, explanation: `The test covers observable behavior and the unhappy path rather than private implementation. Add a real integration test for ${profile.testBoundary}, especially around ${focus[2]}.` },
    { title: "Evidence-first production diagnosis", language: "Diagnostic playbook", code: diagnosticCode, explanation: `This sequence resists symptom-driven guessing. It correlates ${focus[3]} with resource and request evidence before proposing a change.` },
    { title: "Compatible staged rollout and rollback", language: "Release playbook", code: rolloutCode, explanation: `A safe release treats ${profile.artifact} and externally visible state as one compatibility problem. Rollback is tested before deployment, not invented after failure.` }
  ];
}

export function buildGeneratedTechnologyDepth(spec: DepthSpec): TechnologyDepth {
  const profile = profileFor(spec);
  const focus = focusFor(spec);
  const f = (index: number) => focus[index % focus.length];

  return {
    learningPath: [
      { level: "basic", title: "Vocabulary and smallest correct use", objective: `Build and explain a minimal ${spec.title} workflow without hiding behind library slogans.`, topics: [f(0), f(1), "installation, project shape, and version policy", `core units (${profile.unit}) and their invariants`, "input validation, ordinary errors, and resource cleanup"] },
      { level: "intermediate", title: "Idiomatic application boundaries", objective: `Use ${spec.title} in maintainable, tested code with explicit state and dependency boundaries.`, topics: [f(2), f(3), `state ownership across ${profile.state}`, `testing at ${profile.testBoundary}`, `integration through ${profile.boundary}`] },
      { level: "advanced", title: "Runtime, concurrency, and scale", objective: `Predict ${spec.title} behavior under load, failure, concurrency, and constrained resources.`, topics: [f(4), f(5), profile.concurrency, `performance across ${profile.bottleneck}`, "diagnostics, profiling, cancellation, backpressure, and recovery"] },
      { level: "expert", title: "Production and interview judgment", objective: `Defend architecture choices, diagnose incidents, and evolve ${spec.title} without violating compatibility or security.`, topics: [f(6), f(7), `threat modeling at ${profile.securityBoundary}`, "version upgrades, migrations, staged rollout, and rollback", "comparative trade-offs, counterexamples, and system-design cases"] }
    ],
    setup: [
      `Install ${spec.title} from an official distribution or ecosystem package source and record the exact runtime, tool, and plugin versions.`,
      `Create the smallest isolated project, commit its manifest and lock metadata, and verify one build or execution before adding application code.`,
      `Separate local, test, and production configuration; validate required values at startup and keep secrets outside source and generated artifacts.`,
      `Enable the formatter, static checks, focused test command, dependency inspection, and diagnostic tooling used by the project.`,
      `Build the production-shaped ${profile.artifact}, run it in a disposable environment, and exercise startup, one successful path, one rejected path, and graceful shutdown.`
    ],
    runtime: [
      `${spec.mentalModel} The principal execution vocabulary is ${profile.unit}.`,
      `Trace state explicitly across ${profile.state}; distinguish durable state, cached state, request-local state, and derived state.`,
      `The lifecycle is ${profile.lifecycle}. Each transition can allocate resources, expose partial work, or require cleanup.`,
      `Integration crosses ${profile.boundary}. Every crossing needs a contract for validation, timeouts, cancellation, errors, and observability.`,
      `Concurrent behavior involves ${profile.concurrency}; correctness comes from a named invariant and ordering rule, not from timing observed in one run.`
    ],
    testing: [
      `Test the smallest stable policy without booting all of ${spec.title}; include empty, invalid, duplicate, boundary-size, cancelled, and repeated input.`,
      `Use real integration tests at ${profile.testBoundary} where serialization, lifecycle hooks, generated behavior, transactions, or platform semantics define correctness.`,
      `Add property, contract, concurrency, migration, accessibility, or recovery tests when the behavior around ${f(2)} creates a broader invariant than example-based tests cover.`,
      `Keep test data deterministic, control clocks and randomness, assert externally visible behavior, and preserve diagnostic artifacts only for failed runs.`
    ],
    debugging: [
      `Record the ${spec.title} version, resolved dependencies, configuration, input, and first failing boundary before changing code.`,
      `Reproduce the smallest failure and compare a healthy path with the failing path using logs, traces, metrics, state inspection, and generated output.`,
      `For ${f(3)}, locate the first violated invariant rather than the last wrapper error; then test one causal hypothesis at a time.`,
      `Inspect queues, pools, locks, resource pressure, network waits, generated plans or bundles, and lifecycle cleanup when the symptom is intermittent or load-dependent.`
    ],
    performance: [
      `Define the workload and measure throughput, tail latency, allocation or memory, utilization, queue depth, errors, and cost before optimizing ${spec.title}.`,
      `Decompose ${profile.bottleneck}; improve algorithms and data movement before adding caches, pools, batching, or parallelism.`,
      `Bound concurrency and buffers, propagate cancellation and deadlines, and apply backpressure before overload becomes an outage.`,
      `Benchmark representative production shapes, include warm-up and cold-start behavior where relevant, and verify that optimization preserves the invariant.`
    ],
    security: [
      `Threat-model ${profile.securityBoundary}; validate untrusted structure and intent before invoking privileged behavior.`,
      `Authenticate identities, authorize each resource and action, minimize data and permissions, and keep secrets out of source, logs, traces, and client artifacts.`,
      `Pin and review dependencies and plugins, verify provenance where available, patch supported versions, and remove unused attack surface.`,
      `Use safe APIs for queries, templates, paths, commands, deserialization, and transport; log auditable decisions without exposing sensitive values.`
    ],
    failureModes: [
      `Version, plugin, lockfile, runtime, or generated-artifact mismatch makes ${spec.title} behave differently across environments.`,
      `Hidden work around ${f(0)} creates accidental I/O, allocation, queries, rendering, or network calls in a convenient-looking operation.`,
      `Incorrect ownership of ${profile.state} produces stale state, leaks, lost updates, nondeterminism, or unrecoverable partial effects.`,
      `Unbounded work across ${profile.concurrency} exhausts memory, workers, connections, downstream capacity, or retry budgets.`,
      `Observability records symptoms without the identity, version, correlation, or state transition needed to isolate the first failure.`,
      `A change to ${f(6)} breaks compatibility, authorization, stored data, or rollback assumptions even though the build and happy path succeed.`
    ],
    theorySections: [
      section("Core model, vocabulary, and boundaries", `${spec.mentalModel} A rigorous model identifies ${profile.unit}, the invariant each unit owns, and the ${profile.boundary} where representation or responsibility changes. Begin with ${f(0)} and ${f(1)}; distinguish guarantees made by the specification from conveniences supplied by one version or deployment.`, `Name the things ${spec.title} operates on, who owns them, what must remain true, and where control crosses into another subsystem.`, `Think of a well-labelled workshop: each bench owns particular tools and materials, and a handoff ticket records what crosses to the next bench.`, "Software values may be copied, aliased, retried, scheduled, or persisted invisibly, so the actual contract must come from documented semantics and observed state.", `Trace one input through ${f(0)}, across ${profile.boundary}, to an output and cleanup action. Mark every place an error can change ownership.`, [f(0), f(1), `Define invariants for the ${profile.unit}.`, "Separate specification guarantees from common implementation behavior."] ),
      section("Data, state, identity, and lifetime", `${spec.title} distributes state across ${profile.state}. Correctness requires stable identity, explicit ownership, mutation rules, and a lifetime that covers success, rejection, cancellation, retry, and process failure. Relate those rules to ${f(2)}; do not confuse an in-memory reference, cached representation, durable record, and externally committed effect.`, "For every piece of state, answer who created it, who may change it, how long it lives, and how another observer knows it is current.", "A library catalogue, loan record, and physical book are related but different forms of state with different owners and lifetimes.", "Digital state can be copied instantly, observed concurrently, or survive a process in external storage, so physical custody is only an intuition aid.", `Follow ${f(2)} from creation through mutation, serialization or persistence, cache interaction, retry, and final cleanup or archival.`, [f(2), `Classify ${profile.state}.`, "Make identity, mutation, lifetime, and durable effects explicit.", "Design idempotency or compensation for repeated external work."] ),
      section("Execution lifecycle and control flow", `The ${spec.title} lifecycle is ${profile.lifecycle}. Framework hooks and convenient APIs often hide several transitions, so a strong explanation names when configuration becomes fixed, when user work begins, what may run lazily, which failures are translated, and what shutdown must drain. ${f(3)} is easiest to understand as a state transition rather than a list of calls.`, "Draw the states from startup to shutdown and explain which code runs at each transition, including the error and cancellation path.", "A theatre production has rehearsal, doors-open, performance, scene changes, emergency stops, and closing procedures; skipping a stage causes different failures.", "Computer work may be concurrent, speculative, retried, or restored after a crash, unlike a single linear performance.", `Write a timeline for ${f(3)} that includes initialization, one successful operation, an exception or cancellation, resource release, and graceful termination.`, [f(3), profile.lifecycle, "Locate lazy work and hidden lifecycle hooks.", "Treat shutdown and recovery as normal states, not afterthoughts."] ),
      section("Concurrency, ordering, cancellation, and backpressure", `Concurrency in ${spec.title} involves ${profile.concurrency}. First state the shared invariant and required ordering; then choose confinement, immutability, messages, locks, atomics, transactions, queues, or single-writer sequencing. ${f(4)} must include cancellation and bounded demand, because adding workers without capacity control can increase queueing and failure amplification.`, "Several operations can make progress together, but shared state and limited downstream capacity still need one explicit coordination rule.", "A restaurant serves many tables with limited ovens: tickets need ordering, ovens impose capacity, and cancelled orders must stop consuming ingredients.", "Schedulers, memory visibility, distributed delivery, and crash recovery have formal rules that human teamwork does not model precisely.", `Model two competing operations around ${f(4)}. State which orderings are legal, how cancellation propagates, what is bounded, and how overload is signalled.`, [f(4), profile.concurrency, "Distinguish concurrency from parallelism.", "Bound queues, retries, pools, buffers, and in-flight work."] ),
      section("Testing and proof of correctness", `Testing ${spec.title} should mirror ${profile.testBoundary}. Unit tests prove local policy, integration tests prove real boundary semantics, and a small number of end-to-end tests prove critical journeys. For ${f(5)}, include counterexamples, invalid transitions, repeated work, version compatibility, and resource cleanup; a green happy-path test is not evidence for concurrency or recovery.`, "Test each rule at the cheapest boundary that can actually prove it, and move outward only when the real runtime or integration defines the behavior.", "Inspecting a vehicle includes component tests, subsystem tests, a road test, and a crash simulation; repeating only the road test leaves important claims unproved.", "Software tests observe selected executions rather than every possible schedule or input, so invariants may also need types, static checks, property tests, or formal reasoning.", `Create a test matrix for ${f(5)}: ordinary success, malformed input, boundary value, duplicate, timeout, partial dependency failure, restart, and compatible upgrade.`, [f(5), profile.testBoundary, "Assert public behavior and invariants rather than private implementation.", "Use realistic boundaries for generated, serialized, transactional, or concurrent behavior."] ),
      section("Diagnostics, observability, and failure isolation", `Debugging begins by preserving version, configuration, input, identity, timing, and the first incorrect transition. Correlate logs, metrics, traces, profiles, state inspection, and generated artifacts across ${profile.boundary}. For ${f(6)}, compare healthy and failing paths, rule out resource saturation and downstream waits, and change one causal variable before declaring success.`, "Collect evidence that distinguishes competing explanations, then find the earliest state that differs from a healthy run.", "A doctor combines symptoms, history, measurements, and controlled tests; one alarming number is not automatically the cause.", "Software instrumentation can be incomplete, sampled, delayed, or itself costly, so absence of a signal is not proof that an event did not happen.", `Diagnose a regression involving ${f(6)} with a timeline, correlation ID, resource graph, version diff, smallest reproducer, and a regression test for the first violated invariant.`, [f(6), "Separate symptom, correlation, and cause.", "Capture bounded, privacy-aware evidence with stable identities.", "Verify the repair under the original workload and failure condition."] ),
      section("Performance, scaling, and resource economics", `Performance work on ${spec.title} decomposes ${profile.bottleneck}. Complexity, data layout, batching, locality, cache behavior, queueing, contention, serialization, and downstream capacity interact. ${f(7)} should be evaluated with a declared workload and tail distribution; faster median latency can coexist with worse overload recovery, cost, fairness, or correctness.`, "Measure where time and resources are spent, improve the constrained stage, and remeasure the entire path under representative load.", "A road widens traffic only until the next junction becomes the bottleneck; unbounded on-ramps merely move the queue.", "Computer workloads can change shape abruptly and caches can alter the path, so yesterday's bottleneck may not remain today's constraint.", `Build a capacity table for ${f(7)} showing arrival rate, service time, concurrency, queue limit, memory per operation, downstream limit, saturation signal, and safe-shedding behavior.`, [f(7), profile.bottleneck, "Measure percentiles, utilization, queueing, errors, and cost together.", "Prefer algorithm and data-movement improvements before tuning knobs."] ),
      section("Security, compatibility, operations, and trade-offs", `Production ${spec.title} combines ${profile.securityBoundary} with version and data compatibility. Validate at each trust boundary, authorize the resource and action, protect credentials and artifacts, and keep an audit trail for sensitive changes. Stage upgrades of ${profile.artifact}; define rollback triggers, but recognize when external effects or forward-only migrations require roll-forward or compensation instead.`, "A safe feature must resist hostile input, expose only intended authority, remain diagnosable, and change versions without corrupting data or trapping operators.", "A border checkpoint verifies identity and cargo, records entry, limits destinations, and has procedures for policy changes and emergencies.", "Digital identities can be delegated, replayed, or automated at scale, while a rollback may not undo messages, money movement, or leaked data.", `Threat-model one ${spec.title} deployment: enumerate assets, actors, trust boundaries, abuse cases, least-privilege controls, audit signals, compatible rollout steps, rollback limits, and recovery verification.`, [profile.securityBoundary, profile.artifact, "Treat dependencies, plugins, build systems, and generated artifacts as supply-chain boundaries.", "Tie rollout and rollback to measurable correctness and safety signals."] )
    ],
    workedExamples: examples(spec, profile, focus),
    misconceptions: [
      { claim: `${spec.title} is understood once its common API calls are memorized.`, correction: `API recall is useful only after you can explain the ${profile.unit}, lifecycle, state ownership, hidden work, and failure contracts.`, whyItHappens: "Tutorials optimize for a quick successful demo, while interviews and incidents test behavior outside the happy path." },
      { claim: `A successful ${spec.title} build proves the system is correct.`, correction: `A build checks declared syntax and contracts; runtime inputs, integration semantics, concurrency, resources, permissions, and recovery still require evidence.`, whyItHappens: "Fast deterministic feedback is confused with proof of production behavior." },
      { claim: `The shortest ${spec.title} code performs the least work.`, correction: `Convenient abstractions can hide ${profile.bottleneck}; inspect plans, traces, bundles, generated code, queries, or profiles.`, whyItHappens: "Visible source length is used as a proxy for execution cost." },
      { claim: `Adding workers or parallelism always makes ${spec.title} faster.`, correction: `Speedup is bounded by dependencies and capacity; coordination, contention, memory, queues, and downstream saturation can make throughput and latency worse.`, whyItHappens: "Runnable work is mistaken for useful independent work and infinite downstream capacity." },
      { claim: `${spec.title} defaults are production guarantees.`, correction: "Defaults target broad usability and can change by version. Make durability, consistency, timeouts, retries, security, capacity, and lifecycle policy explicit.", whyItHappens: "Local demos rarely exercise failure, load, multi-tenancy, or upgrade constraints." },
      { claim: `Rollback always restores a ${spec.title} deployment to the previous state.`, correction: "Code can roll back while schemas, data, messages, caches, client contracts, credentials, or external effects remain changed; design compatibility and compensation explicitly.", whyItHappens: "Deployment artifacts are confused with the entire distributed state of the system." }
    ],
    revisionChecklist: [
      `Explain the ${spec.title} mental model without product slogans or API lists.`,
      `Define the core units (${profile.unit}) and one invariant each major abstraction owns.`,
      `Trace ${profile.lifecycle} for success, rejection, cancellation, failure, and shutdown.`,
      `Classify ${profile.state} by owner, mutation rule, lifetime, and durability.`,
      `Explain ${f(0)}, ${f(1)}, ${f(2)}, and ${f(3)} with one concrete example each.`,
      `State the ordering, synchronization, cancellation, and backpressure rules around ${f(4)}.`,
      `Design tests across ${profile.testBoundary}, including a counterexample and recovery case.`,
      `Diagnose ${f(6)} from evidence and name the first discriminating signal.`,
      `Measure ${profile.bottleneck} under a declared workload before proposing an optimization.`,
      `Threat-model ${profile.securityBoundary} with least privilege and auditable decisions.`,
      `Plan a compatible version or schema upgrade with staged rollout and realistic rollback limits.`,
      `Answer a design comparison by stating workload, invariant, alternatives, trade-off, and failure signal.`
    ],
    questions: [
      { prompt: `${spec.title}: explain the execution model from input to cleanup.`, difficulty: "easy", answer: `Begin with ${profile.unit}; trace ${profile.lifecycle}; identify ${profile.state}; cross ${profile.boundary}; finish with output, errors, cancellation, and cleanup. Separate documented guarantees from one implementation or deployment.`, whyTricky: "Fluent API usage often masks a weak model of what actually executes.", rubric: ["Names the execution unit and lifecycle.", "Explains state ownership and a concrete boundary.", "Includes failure, cancellation, and cleanup."] },
      { prompt: `${spec.title}: compare ${f(0)} with ${f(1)}.`, difficulty: "medium", answer: `Define each term, show how they interact in ${spec.title}, give one case where either can exist without the other, and choose between designs using the workload, invariant, hidden cost, and failure mode rather than familiarity.`, whyTricky: "Related concepts are often presented together and then treated as synonyms.", rubric: ["Defines both concepts precisely.", "Uses a concrete counterexample or boundary.", "Makes a workload-based trade-off."] },
      { prompt: `${spec.title}: who owns state and when does it become externally committed?`, difficulty: "medium", answer: `Classify ${profile.state}; identify the owner and mutation authority; distinguish temporary, cached, durable, and external effects; then explain transaction, idempotency, cleanup, and recovery boundaries.`, whyTricky: "In-memory success is frequently mistaken for durable or externally visible completion.", rubric: ["Classifies state and ownership.", "Names the commit or visibility boundary.", "Covers retry and recovery."] },
      { prompt: `${spec.title}: design cancellation and overload behavior.`, difficulty: "hard", answer: `Start from ${profile.concurrency}; set deadlines and bounded queues or pools; propagate cancellation across ${profile.boundary}; stop retries when budgets expire; shed optional work; preserve the core invariant; and expose saturation, drops, and timeout signals.`, whyTricky: "Concurrency is discussed as throughput while cancellation, queueing, and downstream capacity are omitted.", rubric: ["Bounds work and resources.", "Propagates cancellation and deadlines.", "Defines overload signals and invariant-preserving degradation."] },
      { prompt: `${spec.title}: build a test strategy for ${f(5)}.`, difficulty: "medium", answer: `Use deterministic unit tests for policy, real integration tests for ${profile.testBoundary}, and a few critical end-to-end journeys. Add malformed, boundary, duplicate, cancellation, partial-failure, restart, migration, and concurrency cases where the invariant requires them.`, whyTricky: "A test pyramid label is not a substitute for choosing boundaries that can prove behavior.", rubric: ["Matches test type to a real boundary.", "Includes unhappy and recovery paths.", "Controls nondeterminism and asserts public behavior."] },
      { prompt: `${spec.title}: diagnose a tail-latency regression after a release.`, difficulty: "hard", answer: `Verify version and workload comparability, split latency across ${profile.boundary}, correlate traces with queue, utilization, allocation and downstream waits, inspect ${profile.bottleneck}, compare healthy and failing cohorts, change one cause, and verify percentiles plus correctness.`, whyTricky: "Average latency and temporal correlation routinely point at the wrong cause.", rubric: ["Uses comparable workload and tail percentiles.", "Decomposes the path with evidence.", "Verifies one causal change without sacrificing correctness."] },
      { prompt: `${spec.title}: name three failures and the signal that distinguishes each.`, difficulty: "medium", answer: `Choose one correctness failure around ${f(2)}, one saturation failure around ${profile.bottleneck}, and one integration or compatibility failure at ${profile.boundary}. Pair each with a distinct invariant, log, trace, metric, state inspection, plan, or artifact diff.`, whyTricky: "Generic lists of possible failures are not actionable without discriminating evidence.", rubric: ["Uses distinct failure classes.", "Pairs each with a useful signal.", "Identifies the first violated invariant."] },
      { prompt: `${spec.title}: optimize ${f(7)} without premature tuning.`, difficulty: "hard", answer: `Declare workload and SLO, profile ${profile.bottleneck}, quantify time and resource cost, improve algorithm or data movement first, introduce bounded batching caching pooling or parallelism only with an invalidation and overload model, then remeasure the full path.`, whyTricky: "Local micro-optimizations can move cost, worsen tails, or violate correctness.", rubric: ["Defines workload and baseline.", "Finds the constrained resource.", "States new trade-offs and verifies end-to-end impact."] },
      { prompt: `${spec.title}: threat-model the most important production boundary.`, difficulty: "hard", answer: `Inventory assets and actors around ${profile.securityBoundary}; map trust boundaries and abuse cases; authenticate identity; authorize resource and action; validate structure and intent; limit privileges and data; protect secrets and artifacts; and define detection, response, and recovery evidence.`, whyTricky: "Security is reduced to input sanitization or authentication while authorization and operational recovery are ignored.", rubric: ["Identifies assets actors and trust boundaries.", "Covers preventive and detective controls.", "Uses least privilege and recovery evidence."] },
      { prompt: `${spec.title}: plan a compatible major-version upgrade.`, difficulty: "hard", answer: `Inventory APIs, plugins, ${profile.artifact}, stored state and client contracts; pin and read compatibility notes; add dual-read or additive changes where needed; test representative behavior; stage cohorts; monitor declared signals; preserve rollback while compatible; and verify recovery.`, whyTricky: "A green compile does not prove data, plugin, operational, or behavioral compatibility.", rubric: ["Inventories more than source compatibility.", "Uses staged migration and observation.", "Explains rollback limits or roll-forward recovery."] },
      { prompt: `${spec.title}: when should you choose an alternative technology?`, difficulty: "medium", answer: `State the workload, invariant, team and operational constraints. Compare execution model, ecosystem, failure semantics, compatibility, observability, security, cost, and exit strategy. Choose ${spec.title} only when its strengths align with the dominant constraints.`, whyTricky: "Preference and ecosystem familiarity are often presented as architecture evidence.", rubric: ["Starts from constraints and invariants.", "Compares multiple operational dimensions.", "Names a condition that reverses the decision."] },
      { prompt: `${spec.title}: give a two-minute production readiness review.`, difficulty: "hard", answer: `Cover pinned versions, configuration validation, ${profile.testBoundary}, resource bounds, timeout and retry budgets, observability, threat model, secrets and identity, compatible data changes, staged release, rollback or compensation, backup and restore, and an owned incident runbook.`, whyTricky: "Feature completeness is confused with operability and recoverability.", rubric: ["Covers correctness performance security and operations.", "Names measurable gates and owners.", "Includes recovery verification."] }
    ],
    flashcards: [
      { front: `${spec.title}: one-sentence mental model`, back: spec.mentalModel },
      { front: `${spec.title}: execution unit`, back: profile.unit },
      { front: `${spec.title}: state inventory`, back: profile.state },
      { front: `${spec.title}: lifecycle`, back: profile.lifecycle },
      { front: `${spec.title}: integration boundary`, back: profile.boundary },
      { front: `${spec.title}: concurrency checklist`, back: `${profile.concurrency}; name ordering, cancellation, bounds, and backpressure.` },
      { front: `${spec.title}: likely constrained resources`, back: profile.bottleneck },
      { front: `${spec.title}: testing boundary`, back: profile.testBoundary },
      { front: `${spec.title}: security boundary`, back: profile.securityBoundary },
      { front: `${spec.title}: first debugging move`, back: "Record version, configuration, input, identity, and the first incorrect transition; compare with a healthy path." },
      { front: `${spec.title}: safe upgrade rule`, back: "Pin → inventory compatibility → test → stage → observe → promote or recover." },
      { front: `${spec.title}: interview answer frame`, back: "Model → invariant → mechanism → example → trade-off → failure signal → verification." }
    ],
    cheatsheet: [
      { title: "A-Z focus map", items: focus.map((item, index) => ({ label: String(index + 1).padStart(2, "0"), value: item })) },
      { title: "Execution and state", items: [{ label: "Unit", value: profile.unit }, { label: "State", value: profile.state }, { label: "Lifecycle", value: profile.lifecycle }, { label: "Boundary", value: profile.boundary }] },
      { title: "Correctness and testing", items: [{ label: "Invariant", value: "name what must remain true" }, { label: "Examples", value: "ordinary + empty + invalid + boundary + duplicate" }, { label: "Failure", value: "timeout + cancellation + partial dependency + restart" }, { label: "Proof", value: profile.testBoundary }] },
      { title: "Performance and operations", items: [{ label: "Measure", value: "throughput + tails + utilization + queues + errors + cost" }, { label: "Constrain", value: profile.bottleneck }, { label: "Overload", value: "bound + backpressure + shed + recover" }, { label: "Diagnose", value: "reproduce → correlate → isolate → change one cause → verify" }] },
      { title: "Security and change", items: [{ label: "Threat model", value: profile.securityBoundary }, { label: "Authority", value: "authenticate identity + authorize resource/action + least privilege" }, { label: "Artifact", value: profile.artifact }, { label: "Release", value: "compatibility → staged rollout → measurable gate → rollback/compensation" }] }
    ]
  };
}

